css:
.tv { font-family: "Inter", -apple-system, "Segoe UI", sans-serif; color: #1e293b; font-size: 13px; line-height: 1.5; }
.tv h1 { text-align: center; font-size: 19px; margin: 0 0 4px; }
.tv h2 { font-size: 12px; text-transform: uppercase; letter-spacing: 0.05em; color: #4f46e5; margin: 18px 0 6px; border-bottom: 1px solid #e2e8f0; padding-bottom: 3px; }
.tv-center { text-align: center; }
.tv-muted { color: #64748b; }
.tv-small { font-size: 11px; margin-top: 20px; }
.tv-head { display: flex; gap: 18px; margin-top: 16px; align-items: flex-start; }
.tv-photo { width: 120px; height: 150px; border: 1px solid #cbd5e1; border-radius: 4px; overflow: hidden; flex-shrink: 0; display: flex; align-items: center; justify-content: center; color: #94a3b8; font-size: 11px; }
.tv-photo img { width: 100%; height: 100%; object-fit: cover; }
.tv-table { width: 100%; border-collapse: collapse; }
.tv-table td { padding: 5px 4px; border-bottom: 1px solid #f1f5f9; vertical-align: top; }
.tv-table td:first-child { width: 34%; color: #64748b; }
.tv-declare { margin-top: 22px; }
.tv-sign { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; margin-top: 44px; }
.tv-line { border-top: 1px solid #1e293b; height: 30px; }
